def postfix_to_prefix(expression: str) -> str:
    stack = []
    for ch in expression:
        if ch.isalnum():
            stack.append(ch)
        else:
            a = stack.pop()   # right operand
            b = stack.pop()   # left operand
            stack.append(ch + b + a)
    return stack[0]

