#include <bits/stdc++.h>
using namespace std;

string postToPre(string post_exp) {
    stack<string> st;
    for (char ch : post_exp) {
        if (isalnum((unsigned char)ch)) st.push(string(1, ch));
        else {
            string a = st.top(); st.pop();
            string b = st.top(); st.pop();
            st.push(ch + b + a);
        }
    }
    return st.top();
}

