import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public String postToPre(String post) {
        Deque<String> stack = new ArrayDeque<>();
        for (char ch : post.toCharArray()) {
            if (Character.isLetterOrDigit(ch)) stack.push(String.valueOf(ch));
            else {
                String a = stack.pop(), b = stack.pop();
                stack.push(ch + b + a);
            }
        }
        return stack.peek();
    }
}
